# Cooper's level-11 recurrence
def Ac(k):
    return (k+_sage_const_1 )**_sage_const_3 

def Bc(k):
    return _sage_const_2 *(_sage_const_2 *k+_sage_const_1 )*(_sage_const_5 *k**_sage_const_2 +_sage_const_5 *k+_sage_const_2 )

def Cc(k):
    return -_sage_const_8 *k*(_sage_const_7 *k**_sage_const_2 +_sage_const_1 )

def Dc(k):
    return _sage_const_22 *k*(_sage_const_2 *k-_sage_const_1 )*(k-_sage_const_1 )

# Compute T_k (Cooper)
print("Computing Cooper's T_k...", flush=True)
T = [QQ(_sage_const_1 )]
# Need T_1: from k=0: 1*T_1 = 2*1*2*T_0 = 4. So T_1 = 4
T.append(QQ(_sage_const_4 ))
# k=1: 8*T_2 = 2*3*12*T_1 - 8*1*8*T_0 = 288 - 64 = 224. T_2 = 28
T.append(QQ(_sage_const_28 ))
KMAX = _sage_const_250 
for k in range(_sage_const_2 , KMAX):
    t_next = (Bc(k)*T[k] + Cc(k)*T[k-_sage_const_1 ] + Dc(k)*T[k-_sage_const_2 ]) / Ac(k)
    T.append(t_next)
print(f"  T_0..T_5 = {T[:_sage_const_6 ]}")

# Compute W_n via binomial transform
print("Computing W_n...", flush=True)
NMAX = _sage_const_60 
W = []
for n in range(NMAX):
    val = QQ(_sage_const_0 )
    for j in range(min(_sage_const_2 *n+_sage_const_1 , len(T))):
        val += binomial(_sage_const_2 *n, j) * QQ(-_sage_const_2 )**(_sage_const_2 *n-j) * T[j]
    W.append(val / QQ(_sage_const_256 )**n)
print(f"  W_0..W_3 = {W[:_sage_const_4 ]}")

# Compute q_n
print("Computing q_n...", flush=True)
q = [QQ(-_sage_const_215040420000 )]
q.append(QQ(-_sage_const_167282265043404 ) / QQ(_sage_const_905 ))
