# Check ratio q_n / (W_n * h_n) for various h_n
print("\n=== Testing h_n = (3/2)_n / n! (central binomial related) ===", flush=True)
from sage.functions.other import rising_factorial as rf

for n in range(min(_sage_const_15 , len(q), len(W))):
    if W[n] != _sage_const_0 :
        h = rf(QQ(_sage_const_3 )/QQ(_sage_const_2 ), n) / factorial(n)
        r = q[n] / (W[n] * h)
        print(f"  n={n}: q/(W*h) = {float(r):.10f}")

# Now check: can q_n be written as sum of u_j(n) * h_n * W_{n+j}?
# where h_n = sqrt(pi) * Gamma(n+3/2) / Gamma(n+1) = (2n+1)!! / 2^n
print("\n=== h_n = (2n+1)!! / 2^n ===", flush=True)
for n in range(min(_sage_const_15 , len(q), len(W))):
    if W[n] != _sage_const_0 :
        h = QQ(_sage_const_1 )
        for j in range(n):
            h *= QQ(_sage_const_2 *j+_sage_const_1 )
        h /= QQ(_sage_const_2 )**n
        r = q[n] / (W[n] * h)
        print(f"  n={n}: q/(W*h) = {float(r):.10f}")

# Now try the POINCARE APPROACH: compute the sequence q_n / W_n
# and see what recurrence IT satisfies
print("\n=== Recurrence for r_n = q_n / W_n ===", flush=True)
r_vals = []
for n in range(min(len(q), len(W))):
    if W[n] != _sage_const_0 :
        r_vals.append(q[n] / W[n])
    else:
        r_vals.append(None)

# Check: r_{n+1}/r_n
print("  r_{n+1}/r_n:")
for n in range(min(_sage_const_15 , len(r_vals)-_sage_const_1 )):
    if r_vals[n] and r_vals[n+_sage_const_1 ]:
        print(f"    n={n}: {float(r_vals[n+_sage_const_1 ]/r_vals[n]):.15f}")

# Search for a rational function of n matching r_{n+1}/r_n
# If r_{n+1}/r_n = P(n)/Q(n), then r_n = prod P(j)/Q(j) which is a hypergeometric twist
print("\n=== Searching for r_{n+1}/r_n = P(n)/Q(n) ===", flush=True)
rr = []
for n in range(min(len(r_vals)-_sage_const_1 , _sage_const_40 )):
    if r_vals[n] and r_vals[n+_sage_const_1 ]:
        rr.append(r_vals[n+_sage_const_1 ] / r_vals[n])

# Try Padé approximant for rr[n] as a function of n
# rr[n] ≈ P(n)/Q(n) where we search for deg P = deg Q = d
R = PolynomialRing(QQ, names=('x',)); (x,) = R._first_ngens(1)
for d in range(_sage_const_1 , _sage_const_10 ):
    # Build system: rr[n] * Q(n) = P(n)
    # P = a_0 + a_1*n + ... + a_d*n^d
    # Q = 1 + b_1*n + ... + b_d*n^d (monic constant term 1... actually let's make leading coeff 1)
    # Q = n^d + b_{d-1}*n^{d-1} + ... + b_0
    n_unk = _sage_const_2 *d + _sage_const_1   # d+1 for P, d for Q (leading coeff of Q fixed to 1)
    n_pts = min(n_unk + _sage_const_5 , len(rr))

    if n_pts < n_unk:
        break

    M = matrix(QQ, n_pts, n_unk)
    b = vector(QQ, n_pts)
    for i in range(n_pts):
        n = i + _sage_const_1   # start from n=1 to avoid issues
        # P coefficients: -n^0, -n^1, ..., -n^d
        for k in range(d+_sage_const_1 ):
            M[i, k] = -QQ(n)**k
        # Q coefficients: rr[i+1] * n^0, ..., rr[i+1] * n^{d-1}
        for k in range(d):
            M[i, d+_sage_const_1 +k] = rr[i+_sage_const_1 ] * QQ(n)**k
        # RHS: -rr[i+1] * n^d (from the leading term of Q)
        b[i] = -rr[i+_sage_const_1 ] * QQ(n)**d

    try:
        sol = M.solve_right(b)
    except ValueError:
        continue

    # Verify on holdout
    ok = True
    for i in range(n_pts, min(n_pts+_sage_const_5 , len(rr))):
        n = i + _sage_const_1 
        P_val = sum(sol[k] * QQ(n)**k for k in range(d+_sage_const_1 ))
        Q_val = QQ(n)**d + sum(sol[d+_sage_const_1 +k] * QQ(n)**k for k in range(d))
        if Q_val == _sage_const_0  or P_val/Q_val != rr[i+_sage_const_1 ]:
            ok = False
            break

    if ok:
        P_coeffs = [sol[k] for k in range(d+_sage_const_1 )]
        Q_coeffs = [sol[d+_sage_const_1 +k] for k in range(d)] + [QQ(_sage_const_1 )]
        P_poly = sum(P_coeffs[k] * x**k for k in range(d+_sage_const_1 ))
        Q_poly = sum(Q_coeffs[k] * x**k for k in range(d+_sage_const_1 ))
        print(f"\n*** MATCH at degree {d}: ***")
        print(f"  r_{{n+1}}/r_n = P(n)/Q(n)")
        print(f"  P(n) = {P_poly}")
        print(f"  Q(n) = {Q_poly}")

        # Extended verification
        all_ok = True
        for i in range(len(rr)):
            n = i + _sage_const_1 
            P_val = P_poly(n)
            Q_val = Q_poly(n)
            if Q_val == _sage_const_0  or P_val/Q_val != rr[i+_sage_const_1 ]:
                all_ok = False
                print(f"  FAIL at n={n}")
                break
        if all_ok:
            print(f"  VERIFIED for all n=1..{len(rr)-_sage_const_1 }")

            # Factor the polynomials
            print(f"  P factors: {P_poly.factor()}")
            print(f"  Q factors: {Q_poly.factor()}")

            # Express h_n = prod_{j=0}^{n-1} P(j)/Q(j) in closed form
            print(f"\n  h_n = r_0 * prod_{{j=0}}^{{n-1}} P(j)/Q(j)")
            print(f"  r_0 = q_0/W_0 = {r_vals[_sage_const_0 ]}")
        break

print("\nDone.")

